INSERT INTO public.services (division_id,slug,name,description,is_active,sort_order) VALUES (1,'shower-tub-tile-detail','Shower, Tub & Tile Detail','Specialized wet-area detail; restoration-level conditions require assessment.',true,30),(1,'carpet-rug-care','Carpet & Rug Care','Carpet, area-rug and extraction/detail services; specialty restoration requires assessment.',true,31),(1,'upholstery-soft-furnishings-care','Upholstery & Soft-Furnishings Care','Soft-furnishing detail and care; specialty fabrics and extraction require appropriate equipment/provider.',true,32),(1,'mattress-bed-care','Mattress & Bed Care','Mattress, bed-frame and accessible bedroom-care service.',true,33),(1,'organization-decluttering-household-reset','Organization, Decluttering & Household Reset','Household organization and decluttering; intentionally separate from cleaning.',true,34),(1,'trash-debris-household-disposal-support','Trash, Debris & Household Disposal Support','Ordinary household debris and disposal coordination; hazardous/regulated material excluded.',true,35) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,is_active=true,sort_order=EXCLUDED.sort_order,updated_at=now();
